begin;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values
 ('c6000000-0000-4000-8000-000000000001','c6-admin@example.invalid',now(),false),
 ('c6000000-0000-4000-8000-000000000002','c6-ops@example.invalid',now(),false),
 ('c6000000-0000-4000-8000-000000000003','c6-editor@example.invalid',now(),false),
 ('c6000000-0000-4000-8000-000000000004','c6-member@example.invalid',now(),false);
insert into public.staff_memberships(user_id,role) values
 ('c6000000-0000-4000-8000-000000000001','admin'),('c6000000-0000-4000-8000-000000000002','operations'),('c6000000-0000-4000-8000-000000000003','editor');
insert into public.content_drafts(id,version,snapshot,created_by,updated_by) values('c6100000-0000-4000-8000-000000000001',1,'{}','c6000000-0000-4000-8000-000000000001','c6000000-0000-4000-8000-000000000001');
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) values('c6100000-0000-4000-8000-000000000002','{}','c6100000-0000-4000-8000-000000000001',1,'c6000000-0000-4000-8000-000000000001');
insert into public.customer_orders(id,user_id,idempotency_key,request_digest,currency,items_minor,shipping_address,terms_release_id) values('c6200000-0000-4000-8000-000000000001','c6000000-0000-4000-8000-000000000004','c6-sql-test',repeat('a',64),'USD',123,'{"name":"Synthetic","country":"US","region":"","city":"Test","postalCode":"","line1":"Test","line2":"","phone":""}','c6100000-0000-4000-8000-000000000002');
insert into public.order_items(order_id,sku_id,product_id,name,quantity,unit_minor,offering_version) select 'c6200000-0000-4000-8000-000000000001',id,product_id,name,1,123,version from public.catalog_offerings where product_id='ola';

insert into public.customer_notes(user_id,note,created_by)values('c6000000-0000-4000-8000-000000000004','private customer note','c6000000-0000-4000-8000-000000000001');
insert into public.order_notes(order_id,note)values('c6200000-0000-4000-8000-000000000001','private order note');
insert into public.payment_attempts(order_id,idempotency_key)values('c6200000-0000-4000-8000-000000000001','privacy-keep');
update public.profiles set display_name='Sensitive',shipping_address='{"line1":"Sensitive address"}' where user_id='c6000000-0000-4000-8000-000000000004';
set local role anon;
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request')$$,'42501',null,'anon denied');
set local role authenticated;
set local request.jwt.claims='{"sub":"c6000000-0000-4000-8000-000000000003","role":"authenticated"}';
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request')$$,'42501',null,'editor denied');
select is(public.get_admin_dashboard()->'customers','null'::jsonb,'editor customer count inaccessible');
select is(public.get_admin_dashboard()->'orders','null'::jsonb,'editor order count inaccessible');
select is(public.get_admin_dashboard()->'waitlist','null'::jsonb,'editor waitlist inaccessible');
select ok(public.get_admin_dashboard()->'drafts'<>'null'::jsonb,'editor drafts available');
select throws_ok($$select public.get_customer_privacy_workspace()$$,'42501',null,'editor jobs denied');
set local request.jwt.claims='{"sub":"c6000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request')$$,'42501',null,'operations cannot erase');
select is(public.get_admin_dashboard()->'drafts','null'::jsonb,'operations drafts inaccessible');
set local request.jwt.claims='{"sub":"c6000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(public.get_customer_privacy_workspace()->>'enabled','false','production default closed');
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request')$$,'42501',null,'admin direct RPC cannot bypass policy');
select throws_ok($$update private.customer_privacy_policy set enabled=true,revision='caller'$$,'42501',null,'caller cannot confirm policy');
select throws_ok($$select public.anonymize_customer_data(gen_random_uuid(),gen_random_uuid())$$,'42501',null,'admin cannot call worker RPC');
select throws_ok($$select * from public.customer_privacy_jobs$$,'42501',null,'admin no raw lease access');
reset role;
update private.customer_privacy_policy set enabled=true,revision='isolated-test-v1';
update public.staff_memberships set active=false where user_id='c6000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000002','customer_request')$$,'42501',null,'inactive staff target rejected');
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000001','customer_request')$$,'42501',null,'last effective admin target rejected');
select throws_ok($$select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','raw personal reason')$$,'22023',null,'free-text PII reason rejected');
create temporary table c6_job as select public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request') j;
select is(public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request')->>'jobId',(select j->>'jobId' from c6_job),'repeated start same job');
select is(public.get_customer_privacy_workspace('c6000000-0000-4000-8000-000000000004')->'jobs'->>'total','1','jobs searchable durable list');
select is(public.get_customer_privacy_workspace('',99)->'jobs'->'items','[]'::jsonb,'empty out-of-range page');
select throws_ok($$select public.add_customer_note('c6000000-0000-4000-8000-000000000004','late PII')$$,'42501',null,'customer note after suspension denied');
select throws_ok($$select public.add_order_note('c6200000-0000-4000-8000-000000000001','late PII')$$,'42501',null,'order note after suspension denied');
set local request.jwt.claims='{"sub":"c6000000-0000-4000-8000-000000000004","role":"authenticated"}';
select is((select count(*) from public.profiles),0::bigint,'suspended old JWT cannot read personal profile');
select is((select count(*) from public.customer_orders),0::bigint,'suspended old JWT cannot read orders');
select throws_ok($$select public.create_customer_order('{}')$$,'42501',null,'suspended cannot create order');
reset role;
grant select on c6_job to service_role;
set local role service_role;
select throws_ok($$update private.customer_privacy_policy set enabled=true$$,'42501',null,'service cannot confirm policy');
select throws_ok($$select public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000003')$$,'42501',null,'service claim rechecks current admin');
create temporary table c6_claim as select public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000001') c;
select throws_ok($$select public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000001')$$,'23505',null,'concurrent lease rejected');
select throws_ok($$select public.anonymize_customer_data((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim))$$,'23514',null,'cannot claim completed without actual Auth ban');
select is(public.fail_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim),'auth_ban')->>'status','failed','durable failure not completion');
select throws_ok($$select public.anonymize_customer_data((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim))$$,'23505',null,'old lease invalid after failure');
reset role;
select is((select access_state from public.profiles where user_id='c6000000-0000-4000-8000-000000000004'),'suspended','failure retains suspension');
select is((select display_name from public.profiles where user_id='c6000000-0000-4000-8000-000000000004'),'Sensitive','application data not falsely cleared');
-- SQL tests simulate already verified Auth storage; separate real SDK/browser test verifies actual API semantics.
update auth.users set banned_until=now()+interval '100 years',email='erased-c6000000-0000-4000-8000-000000000004@example.invalid',phone=null,raw_user_meta_data='{}',raw_app_meta_data='{}' where id='c6000000-0000-4000-8000-000000000004';
update private.customer_privacy_policy set revision='changed';
set local role service_role;
select throws_ok($$select public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000001')$$,'42501',null,'changed retention scope cannot resume');
reset role;
update private.customer_privacy_policy set revision='isolated-test-v1';
insert into auth.users(id,email,email_confirmed_at,is_anonymous)values('c6000000-0000-4000-8000-000000000005','c6-new-admin@example.invalid',now(),false);
insert into public.staff_memberships(user_id,role)values('c6000000-0000-4000-8000-000000000005','admin');
update public.staff_memberships set active=false where user_id='c6000000-0000-4000-8000-000000000001';
set local role service_role;
select throws_ok($$select public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000001')$$,'42501',null,'departed initiator cannot claim');
select lives_ok($$select public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000005')$$,'another current admin can recover departed initiator job');
reset role;
update public.customer_privacy_jobs set lease_until=now()-interval '1 second' where user_id='c6000000-0000-4000-8000-000000000004';
update public.staff_memberships set active=true where user_id='c6000000-0000-4000-8000-000000000001';
set local role service_role;
update c6_claim set c=public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000001');
reset role;
update private.customer_privacy_policy set enabled=false;
set local role service_role;
select throws_ok($$select public.anonymize_customer_data((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim))$$,'42501',null,'disabled policy blocks direct worker erasure even existing lease');
reset role;
update private.customer_privacy_policy set enabled=true;
create function pg_temp.c6_audit_failure() returns trigger language plpgsql as $$begin if new.action='customers.anonymization_completed' then raise exception 'synthetic audit failure';end if;return new;end;$$;
create trigger c6_audit_failure before insert on public.audit_events for each row execute function pg_temp.c6_audit_failure();
set local role service_role;
select throws_ok($$select public.anonymize_customer_data((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim))$$,'P0001','synthetic audit failure','audit failure rolls back all erasure');
reset role;
select is((select display_name from public.profiles where user_id='c6000000-0000-4000-8000-000000000004'),'Sensitive','audit failure cannot partially clear profile');
select is((select count(*) from public.customer_notes where user_id='c6000000-0000-4000-8000-000000000004'),1::bigint,'audit failure retains subject notes atomically');
select is((select status from public.customer_privacy_jobs where user_id='c6000000-0000-4000-8000-000000000004'),'pending','audit failure cannot mark completed');
drop trigger c6_audit_failure on public.audit_events;
update auth.users set email_change='pending-private@example.invalid' where id='c6000000-0000-4000-8000-000000000004';
set local role service_role;
select throws_ok($$select public.anonymize_customer_data((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim))$$,'23514',null,'uncleared pending Auth contact prevents completion');
reset role;
update auth.users set email_change='' where id='c6000000-0000-4000-8000-000000000004';
set local role service_role;
select is(public.anonymize_customer_data((select(j->>'jobId')::uuid from c6_job),(select(c->>'leaseToken')::uuid from c6_claim))->>'status','completed','verified Auth allows application completion');
select is(public.claim_customer_privacy_job((select(j->>'jobId')::uuid from c6_job),'c6000000-0000-4000-8000-000000000001')->>'status','completed','completed resume idempotent');
reset role;
select is((select shipping_address from public.customer_orders where id='c6200000-0000-4000-8000-000000000001'),'{}'::jsonb,'shipping scrubbed');
select is((select items_minor from public.customer_orders where id='c6200000-0000-4000-8000-000000000001'),123::bigint,'financial order retained');
select is((select unit_minor from public.order_items where order_id='c6200000-0000-4000-8000-000000000001'),123::bigint,'immutable line item retained');
select is((select count(*) from public.payment_attempts where order_id='c6200000-0000-4000-8000-000000000001'),1::bigint,'payment FK retained');
select is((select count(*) from public.customer_notes where user_id='c6000000-0000-4000-8000-000000000004'),0::bigint,'customer notes actually removed');
select is((select count(*) from public.order_notes where order_id='c6200000-0000-4000-8000-000000000001'),0::bigint,'order notes actually removed');
select is((select display_name||shipping_address::text||access_state from public.profiles where user_id='c6000000-0000-4000-8000-000000000004'),'{}anonymized','profile actually scrubbed');
select is((select count(*) from auth.users where id='c6000000-0000-4000-8000-000000000004'),1::bigint,'Auth UUID retained');
select ok(not exists(select 1 from public.audit_events where entity_id=(select(j->>'jobId')::uuid from c6_job) and summary::text ~ 'Sensitive|private customer note|private order note'),'audit no raw PII');
set local role authenticated;
set local request.jwt.claims='{"sub":"c6000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is(public.request_customer_anonymization('c6000000-0000-4000-8000-000000000004','customer_request')->>'status','completed','completed request idempotent');
select throws_ok($$select public.add_order_note('c6200000-0000-4000-8000-000000000001','restored PII')$$,'42501',null,'no notes can return after erase');
reset role;
select is(public.get_admin_dashboard()->>'orders',(select count(*)::text from public.customer_orders),'dashboard actual count');
select ok(not(public.get_admin_dashboard()?'revenue'),'no revenue inference');
select * from finish();
rollback;
